import type { Topic } from "@/lib/study/schema";

/**
 * CN depth topics, part A (Kurose ch. 1, 4, 6, 7; Forouzan). Numbers from lib/study/cn2.ts, checked by script:
 * 100 Mbps, 2000 km at 200 km/ms, 1500 B, 5000 pkt/s: prop 10 ms, trans 0.12 ms, RTT 20 ms, BDP 1,000,000 bits = 125,000 B, intensity 0.6.
 * Hamming 1011 → 0110011 (p1 0, p2 1, p4 0); 0110111 → syndrome 5; 10011010 → 011100101010 with 4 parity bits. 7 data bits need 4, 11 need 4.
 * Switch trace: A→B floods 2,3,4; B→A forwards 1; C→A forwards 1; A→C forwards 3; D→A on port 1 filtered. Min frame 10 Mbps × 51.2 µs = 512 bits.
 * 802.11 at 54 Mbps, 1500 B, 7 slots: 337.3 µs, 65.9% efficiency, 35.6 Mbps; with RTS/CTS 374.3 µs, 32.1 Mbps.
 * NAT 203.0.113.5: 10.0.0.2:3345 → 5001, 10.0.0.3:3345 → 5002, 10.0.0.2:4000 → 5003; 3 entries.
 * IPv6: 2001:db8::1 expands to 2001:0db8:0000:0000:0000:0000:0000:0001; 2001:0db8:0000:0000:0000:ff00:0042:8329 → 2001:db8::ff00:42:8329.
 * Classes: 10.20.30.40 A /8 16,777,214 hosts; 172.16.5.4 B; 200.1.2.3 C 254; 230.0.0.1 D. 200.1.0.0–200.1.3.0 → 200.1.0.0/22 exact; 200.1.1.0 + 200.1.2.0 not exact.
 */
