      steps: [{ say: "5000 × 12 000 / 10⁸.", result: "0.6" }, { say: "9000 × 12 000 / 10⁸ = 1.08 > 1.", result: "unbounded queue" }],
      answer: "0.6: moderate queueing. At 9000 per second, 1.08: the queue grows without limit and packets are dropped.",
